// toPrecision(30) muestra el valor exacto guardado (hasta 30 dígitos)
console.log("0.1  =", (0.1).toPrecision(30));
console.log("0.2  =", (0.2).toPrecision(30));
console.log("0.3  =", (0.3).toPrecision(30));
console.log("suma =", (0.1 + 0.2).toPrecision(30));

console.log(0.1 + 0.2);            // 0.30000000000000004
console.log(0.1 + 0.2 === 0.3);    // false
console.log(0.5 + 0.25 === 0.75);  // true: son sumas de mitades

// Al repetir la suma, el error crece
let s = 0;
for (let i = 0; i < 10; i++) s += 0.1;
console.log("diez veces 0.1:", s, s === 1);   // 0.9999999999999999 false

// Float de 32 bits: Math.fround redondea a ese formato
console.log("0.1 en float32:", Math.fround(0.1).toPrecision(25));

// Igualdad con tolerancia relativa y un piso absoluto
function casiIgual(a, b, relativa = 1e-9, absoluta = 1e-12) {
  const diferencia = Math.abs(a - b);
  return diferencia <= Math.max(absoluta, relativa * Math.max(Math.abs(a), Math.abs(b)));
}

console.log(0.1 + 0.2 === 0.3);          // false
console.log(casiIgual(0.1 + 0.2, 0.3));  // true

// Number.EPSILON como tolerancia solo sirve cerca de 1
const a = 1000 + 0.1 + 0.2;
const b = 1000.3;
console.log(Math.abs(a - b) < Number.EPSILON);  // false, aunque son «lo mismo»
console.log(casiIgual(a, b));                    // true

// 10.000 recargos de 10 centavos: con coma flotante
let flotante = 0;
for (let i = 0; i < 10000; i++) flotante += 0.1;
console.log(flotante, flotante === 1000);     // 1000.0000000001588 false

// Los mismos, en centavos enteros
let centavos = 0;
for (let i = 0; i < 10000; i++) centavos += 10;
console.log(centavos, centavos === 100000);   // 100000 true

// Para mostrar: separar pesos y centavos con enteros
const pesos = Math.trunc(centavos / 100);
const resto = String(centavos % 100).padStart(2, "0");
console.log(`$ ${pesos.toLocaleString("es-AR")},${resto}`);   // $ 1.000,00

